tile_tidal_chart.query:
timeseries {
  water_level = avg(`buoy.tidal.water.level.meters`),
  tidal_rate  = avg(`buoy.tidal.rate.cm.per.hour`),
  tidal_range = avg(`buoy.tidal.range.meters`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_atm_co2_pressure.query:
timeseries {
  co2      = avg(`buoy.atm.co2.ppm`),
  pressure = avg(`buoy.atm.pressure.hpa`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_atm_wind_temp.query:
timeseries {
  wind_speed = avg(`buoy.atm.wind.speed.knots`),
  air_temp   = avg(`buoy.atm.air.temp.celsius`),
  humidity   = avg(`buoy.atm.humidity.percent`),
  solar      = avg(`buoy.atm.solar.irradiance.wm2`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_ocean_temp_salinity.query:
timeseries {
  surf_temp = avg(`buoy.ocean.surface.temp.celsius`),
  sub_temp  = avg(`buoy.ocean.subsurface.temp.celsius`),
  salinity  = avg(`buoy.ocean.salinity.psu`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_ocean_ph_o2.query:
timeseries {
  ph       = avg(`buoy.ocean.ph`),
  do2      = avg(`buoy.ocean.dissolved.oxygen.mgl`),
  turb     = avg(`buoy.ocean.turbidity.ntu`),
  chloro   = avg(`buoy.ocean.chlorophyll.ugl`),
  dco2     = avg(`buoy.ocean.dissolved.co2.umol`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_wave_heights.query:
timeseries {
  hs     = avg(`buoy.wave.significant.height.meters`),
  hmax   = avg(`buoy.wave.max.height.meters`),
  tp     = avg(`buoy.wave.peak.period.seconds`),
  swell  = avg(`buoy.wave.swell.height.meters`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))

tile_current_chart.query:
timeseries {
  surf_spd  = avg(`buoy.current.surface.speed.knots`),
  sub_spd   = avg(`buoy.current.subsurface.speed.knots`),
  surf_dir  = avg(`buoy.current.surface.direction.degrees`),
  vert      = avg(`buoy.current.vertical.cm.per.sec`)
}, by: {buoy_id}
| filter isNull(array($buoy)[0]) or in(buoy_id, array($buoy))
